import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Conformance vectors","description":"","frontmatter":{},"headers":[],"relativePath":"reference/conformance.md","filePath":"reference/conformance.md"}'),n={name:"reference/conformance.md"};function s(c,e,d,i,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="conformance-vectors" tabindex="-1">Conformance vectors <a class="header-anchor" href="#conformance-vectors" aria-label="Permalink to &quot;Conformance vectors&quot;">​</a></h1><p>Every binding must produce the same samples as the core, bit for bit. Shared <strong>conformance vectors</strong> check it in CI on every pull request.</p><h2 id="what-a-vector-is" tabindex="-1">What a vector is <a class="header-anchor" href="#what-a-vector-is" aria-label="Permalink to &quot;What a vector is&quot;">​</a></h2><p>One input (text, voice, seed, sample rate) and its expected result: the number of samples, a hash of the samples, the duration and every event (position in the text, times, sound variant). Four vectors expect an error instead (pitch, speed, variation, sample rate out of range).</p><p>There are 34: ten inputs for each style, covering accents, emoji, empty text, punctuation only, Windows line endings, long text, sample rates from 8 to 192 kHz and seeds up to the maximum, plus the four error cases.</p><h2 id="the-hash" tabindex="-1">The hash <a class="header-anchor" href="#the-hash" aria-label="Permalink to &quot;The hash&quot;">​</a></h2><p>64-bit FNV-1a (offset <code>0xcbf29ce484222325</code>, prime <code>0x100000001b3</code>) over the little-endian bytes of the 32-bit float samples, written as a hex string. It is easy to write in any language: each suite computes it itself.</p><h2 id="where-they-run" tabindex="-1">Where they run <a class="header-anchor" href="#where-they-run" aria-label="Permalink to &quot;Where they run&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Platforms</th><th>How</th></tr></thead><tbody><tr><td>Rust core</td><td>Linux x64, Windows x64, macOS arm64</td><td><code>cargo test</code> (debug and release)</td></tr><tr><td>WebAssembly</td><td>Node</td><td>Vitest in <code>packages/web</code></td></tr><tr><td>C ABI</td><td>Linux, Windows, macOS universal (and x86_64 under Rosetta)</td><td>CTest in <code>bindings/c</code></td></tr><tr><td>Godot</td><td>Godot 4.3 and 4.7.2 on Linux</td><td>headless GDScript tests</td></tr><tr><td>C# (Unity interop)</td><td>.NET 8 on Linux, C# 9</td><td><code>bindings/unity/DotnetTests~</code>; the same checks run as Unity EditMode tests</td></tr></tbody></table><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><p>They are generated from the core by <code>cargo run -p mumble-conformance -- generate</code>:</p><ul><li><code>conformance/vectors.json</code> (format 2);</li><li><code>bindings/c/tests/vectors.h</code> for C;</li><li><code>bindings/unity/Tests/EditMode/Vectors.cs</code> for C#.</li></ul><p><code>cargo run -p mumble-conformance -- check</code> (and <code>cargo test</code>) fails if the committed files differ from what the core produces. They are regenerated only for an intentional change of behavior, which is first written in the specs; the diff then shows exactly which outputs changed.</p>',13)])])}const f=t(n,[["render",s]]);export{u as __pageData,f as default};
